package cn.pi.dailyone;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageInfo;import android.net.Uri;import java.net.*;import java.io.*;import java.util.concurrent.*;import org.json.JSONObject;
/** User-initiated update check; never sends LeetCode cookies to GitHub. */
final class UpdateController {
 private final Activity activity;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private AlertDialog loading;private volatile boolean closed;private boolean checking;private int epoch;
 UpdateController(Activity a){activity=a;}
 void check(){if(closed||checking)return;checking=true;final int attempt=++epoch;loading=new AlertDialog.Builder(activity).setTitle("检查更新").setMessage("正在查询最新版本…").setNegativeButton("取消",(d,w)->{if(attempt==epoch){epoch++;checking=false;}}).create();loading.setOnCancelListener(d->{if(attempt==epoch){epoch++;checking=false;}});loading.show();
 worker.execute(()->{try{JSONObject manifest=fetch();long remote=manifest.getLong("versionCode");String name=manifest.getString("versionName"),url=manifest.getString("apkUrl"),notes=manifest.optString("releaseNotes");if(name.isEmpty()||name.length()>80||!UpdatePolicy.trustedApk(url))throw new IOException("更新信息格式不正确");PackageInfo local=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);boolean available=UpdatePolicy.newer(local.versionCode,remote);if(notes.length()>4000)notes=notes.substring(0,4000);final String text=notes;
 ui.post(()->{if(!finish(attempt))return;if(!available){new AlertDialog.Builder(activity).setTitle("检查更新").setMessage("已是最新版（"+local.versionName+"）").setPositiveButton("确定",null).show();return;}new AlertDialog.Builder(activity).setTitle("发现新版本 "+name).setMessage((text.isEmpty()?"有新的安装包可供下载。":text)+"\n\n当前版本："+local.versionName).setPositiveButton("下载安装包",(d,w)->{try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){error("无法打开下载链接，请稍后重试");}}).setNegativeButton("稍后",null).show();});
 }catch(Exception e){final String message=e instanceof SocketTimeoutException?"连接超时，请稍后重试":e.getMessage()!=null?e.getMessage():"无法读取更新信息";ui.post(()->{if(finish(attempt))error(message);});}});}
 private JSONObject fetch()throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(UpdatePolicy.MANIFEST).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setUseCaches(false);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","DailyOne-Android");try{int status=c.getResponseCode();if(status!=200)throw new IOException(status==404?"更新信息暂未发布，请稍后重试":"更新服务器返回 HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(out.size()+n>65536)throw new IOException("更新信息过大");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 private boolean finish(int attempt){if(closed||attempt!=epoch)return false;checking=false;if(loading!=null){loading.dismiss();loading=null;}return true;}
 private void error(String message){if(!closed)new AlertDialog.Builder(activity).setTitle("检查更新失败").setMessage(message).setPositiveButton("确定",null).show();}
 void close(){closed=true;epoch++;checking=false;if(loading!=null)loading.dismiss();worker.shutdownNow();}
}
